#include "PackedPostingList.h"
#include <iostream>
int main(){me::PackedPostingList p;std::vector<uint32_t> v;uint32_t seed=7;auto next=[&](){seed^=seed<<13;seed^=seed>>17;seed^=seed<<5;return seed;};for(uint32_t i=0;i<4096;++i){p.push_back(i*1000);v.push_back(i*1000);}for(unsigned n=0;n<16000;++n){if(!v.empty()&&next()%3==0){size_t rank=next()%v.size();p.erase(p.begin()+rank);v.erase(v.begin()+rank);}else{uint32_t val=n%7?next():0;auto a=std::lower_bound(p.begin(),p.end(),val);auto b=std::lower_bound(v.begin(),v.end(),val);assert(a-p.begin()==b-v.begin());p.insert(a,val);v.insert(b,val);}assert(p.size()==v.size());assert(std::equal(p.begin(),p.end(),v.begin(),v.end()));for(int k=0;k<3;++k){size_t rank=next()%v.size();assert(p[rank]==v[rank]);auto it=p.end();--it;assert(*it==v.back());}}while(!v.empty()){p.erase(p.begin());v.erase(v.begin());if(v.size()%128==0)assert(std::equal(p.begin(),p.end(),v.begin(),v.end()));}p.push_back(UINT32_MAX);assert(p[0]==UINT32_MAX);std::cout<<"16000 mixed mutations + erase-to-empty + UINT32_MAX pass\n";}
